// On-device proof for the GAT + decimate stages (shaders/gat.comp).
//
// Usage: srp_proof_gat <gat.spv> <ref_dir> <fixtures_dir> <gpuref_dir>
// Runs SrpGatGpu op 0 (GAT) and op 1 (decimate) on-device and compares:
//   * real-burst 1024x1024 frame-0 crop + real alpha/beta (<ref_dir>:
//     gat_burst_in/alpha/beta/out, decimate_burst_out), generated by
//     /tmp/gen_gat_refs.py from the unmodified CPU source. The crop holds
//     integer raw values (rawpy raw_image_visible, like the port's parity),
//     so decimate must be bit-exact here.
//   * synthetic 32x32 float parity fixtures (<fixtures_dir>) against the
//     port's own GPU outputs (<gpuref_dir>/gpu_gat_out_vst,
//     gpu_decimate_out_grey): bit-exact, same shader and device class.
// Gates (parity_gpu_report.json, never weakened):
//   burst op 0: maxabs <= 9.765625e-4 AND maxrel <= 2.393880436102336e-07
//   burst op 1: bit-exact (maxabs == 0)
//   fixture ops: bit-exact vs the port's recorded GPU output
// Prints per-case numbers; exits nonzero on any breach.

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

#include <vulkan/vulkan.h>

#include "npy.h"
#include "srp_context.h"
#include "srp_pipeline.h"

namespace {

constexpr float kGatMaxAbs = 9.765625e-4f;          // gpu_gat_f00
constexpr double kGatMaxRel = 2.393880436102336e-07;  // gpu_gat_f00

bool FindMemoryType(VkPhysicalDevice physical, uint32_t type_bits,
                    VkMemoryPropertyFlags flags, uint32_t* out_index) {
  VkPhysicalDeviceMemoryProperties props{};
  vkGetPhysicalDeviceMemoryProperties(physical, &props);
  for (uint32_t i = 0; i < props.memoryTypeCount; ++i) {
    if ((type_bits & (1u << i)) != 0u &&
        (props.memoryTypes[i].propertyFlags & flags) == flags) {
      *out_index = i;
      return true;
    }
  }
  return false;
}

bool MakeBuffer(VkDevice device, VkPhysicalDevice physical, VkDeviceSize bytes,
                const float* src, VkBuffer* out_buffer,
                VkDeviceMemory* out_memory) {
  VkBufferCreateInfo buffer_info{};
  buffer_info.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
  buffer_info.size = bytes;
  buffer_info.usage = VK_BUFFER_USAGE_STORAGE_BUFFER_BIT;
  buffer_info.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
  if (vkCreateBuffer(device, &buffer_info, nullptr, out_buffer) != VK_SUCCESS) {
    return false;
  }
  VkMemoryRequirements req{};
  vkGetBufferMemoryRequirements(device, *out_buffer, &req);
  uint32_t index = 0;
  if (!FindMemoryType(physical, req.memoryTypeBits,
                      VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT |
                          VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
                      &index)) {
    vkDestroyBuffer(device, *out_buffer, nullptr);
    return false;
  }
  VkMemoryAllocateInfo alloc{};
  alloc.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
  alloc.allocationSize = req.size;
  alloc.memoryTypeIndex = index;
  if (vkAllocateMemory(device, &alloc, nullptr, out_memory) != VK_SUCCESS) {
    vkDestroyBuffer(device, *out_buffer, nullptr);
    return false;
  }
  if (vkBindBufferMemory(device, *out_buffer, *out_memory, 0) != VK_SUCCESS) {
    vkFreeMemory(device, *out_memory, nullptr);
    vkDestroyBuffer(device, *out_buffer, nullptr);
    return false;
  }
  void* mapped = nullptr;
  if (vkMapMemory(device, *out_memory, 0, bytes, 0, &mapped) != VK_SUCCESS) {
    return false;
  }
  if (src != nullptr) {
    std::memcpy(mapped, src, static_cast<size_t>(bytes));
  } else {
    std::memset(mapped, 0, static_cast<size_t>(bytes));
  }
  vkUnmapMemory(device, *out_memory);
  return true;
}

void FreeBuffer(VkDevice device, VkBuffer buffer, VkDeviceMemory memory) {
  if (buffer != VK_NULL_HANDLE) vkDestroyBuffer(device, buffer, nullptr);
  if (memory != VK_NULL_HANDLE) vkFreeMemory(device, memory, nullptr);
}

std::vector<uint8_t> ReadFile(const char* path) {
  std::vector<uint8_t> bytes;
  if (FILE* f = std::fopen(path, "rb")) {
    std::fseek(f, 0, SEEK_END);
    const long n = std::ftell(f);
    std::fseek(f, 0, SEEK_SET);
    if (n > 0) {
      bytes.resize(static_cast<size_t>(n));
      bytes.resize(std::fread(bytes.data(), 1, bytes.size(), f));
    }
    std::fclose(f);
  }
  return bytes;
}

// Runs one op and reads `count` floats back into `got`. Returns false on
// any setup/dispatch failure.
bool RunOp(srp::Context* ctx, VkShaderModule module, uint32_t width,
           uint32_t height, uint32_t count, uint32_t op,
           const std::vector<float>& in, const std::vector<float>& ab,
           std::vector<float>* got) {
  auto* device = static_cast<VkDevice>(srp::NativeDevice(ctx));
  auto* physical = static_cast<VkPhysicalDevice>(srp::NativePhysicalDevice(ctx));
  VkBuffer in_buf = VK_NULL_HANDLE, out_buf = VK_NULL_HANDLE,
           ab_buf = VK_NULL_HANDLE;
  VkDeviceMemory in_mem = VK_NULL_HANDLE, out_mem = VK_NULL_HANDLE,
                 ab_mem = VK_NULL_HANDLE;
  bool ok = false;
  if (MakeBuffer(device, physical, in.size() * sizeof(float), in.data(),
                 &in_buf, &in_mem) &&
      MakeBuffer(device, physical,
                 static_cast<VkDeviceSize>(count) * sizeof(float), nullptr,
                 &out_buf, &out_mem) &&
      MakeBuffer(device, physical, ab.size() * sizeof(float), ab.data(),
                 &ab_buf, &ab_mem) &&
      srp::SrpGatGpu(ctx, width, height, count, op, in_buf, out_buf, ab_buf,
                      module) == srp::Status::kOk) {
    void* mapped = nullptr;
    if (vkMapMemory(device, out_mem, 0,
                    static_cast<VkDeviceSize>(count) * sizeof(float), 0,
                    &mapped) == VK_SUCCESS) {
      got->assign(static_cast<const float*>(mapped),
                  static_cast<const float*>(mapped) + count);
      vkUnmapMemory(device, out_mem);
      ok = true;
    }
  }
  FreeBuffer(device, in_buf, in_mem);
  FreeBuffer(device, out_buf, out_mem);
  FreeBuffer(device, ab_buf, ab_mem);
  return ok;
}

bool CheckGat(const char* name, const std::vector<float>& got,
              const std::vector<float>& want) {
  if (got.size() != want.size()) {
    std::fprintf(stderr, "FAIL %s: size %zu vs %zu\n", name, got.size(),
                 want.size());
    return false;
  }
  float maxabs = 0.0f;
  double maxrel = 0.0;
  for (size_t i = 0; i < got.size(); ++i) {
    const float d = std::fabs(got[i] - want[i]);
    if (d > maxabs) maxabs = d;
    if (std::fabs(want[i]) > 1e-30f) {
      const double r = static_cast<double>(d) / std::fabs(want[i]);
      if (r > maxrel) maxrel = r;
    }
  }
  const bool pass = maxabs <= kGatMaxAbs && maxrel <= kGatMaxRel;
  std::printf("%s: n=%zu maxabs=%.6g (bound %.6g) maxrel=%.6g (bound %.6g) %s\n",
              name, got.size(), static_cast<double>(maxabs),
              static_cast<double>(kGatMaxAbs), maxrel, kGatMaxRel,
              pass ? "PASS" : "FAIL");
  return pass;
}

bool CheckExact(const char* name, const std::vector<float>& got,
                const std::vector<float>& want) {
  if (got.size() != want.size()) {
    std::fprintf(stderr, "FAIL %s: size %zu vs %zu\n", name, got.size(),
                 want.size());
    return false;
  }
  float maxabs = 0.0f;
  for (size_t i = 0; i < got.size(); ++i) {
    maxabs = std::fmax(maxabs, std::fabs(got[i] - want[i]));
  }
  const bool pass = maxabs == 0.0f;
  std::printf("%s: n=%zu maxabs=%.6g (bit-exact) %s\n", name, got.size(),
              static_cast<double>(maxabs), pass ? "PASS" : "FAIL");
  return pass;
}

bool Load(const std::string& dir, const char* name, srp_proof::NpyArray* out) {
  return srp_proof::LoadNpy((dir + "/" + name).c_str(), out);
}

}  // namespace

int main(int argc, char** argv) {
  if (argc != 5) {
    std::fprintf(stderr,
                 "usage: %s <gat.spv> <ref_dir> <fixtures_dir> <gpuref_dir>\n",
                 argv[0]);
    return 2;
  }
  const std::string ref_dir = argv[2];
  const std::string fix_dir = argv[3];
  const std::string gpu_dir = argv[4];

  srp::Context* ctx = nullptr;
  if (srp::Create(&ctx) != srp::Status::kOk || ctx == nullptr) {
    std::fprintf(stderr, "FAIL: srp::Create failed\n");
    return 1;
  }
  std::printf("device: %s\n", srp::DeviceInfo(ctx).c_str());
  auto* device = static_cast<VkDevice>(srp::NativeDevice(ctx));

  const std::vector<uint8_t> spirv = ReadFile(argv[1]);
  if (spirv.empty() || spirv.size() % 4 != 0) {
    std::fprintf(stderr, "FAIL: cannot read spv %s\n", argv[1]);
    srp::Destroy(ctx);
    return 1;
  }
  VkShaderModuleCreateInfo module_info{};
  module_info.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
  module_info.codeSize = spirv.size();
  module_info.pCode = reinterpret_cast<const uint32_t*>(spirv.data());
  VkShaderModule module = VK_NULL_HANDLE;
  if (vkCreateShaderModule(device, &module_info, nullptr, &module) != VK_SUCCESS) {
    std::fprintf(stderr, "FAIL: shader module create failed\n");
    srp::Destroy(ctx);
    return 1;
  }

  int failures = 0;
  srp_proof::NpyArray in, alpha, beta, want;
  std::vector<float> got;

  // Case 1: GAT on the real-burst 1024 crop with real alpha/beta.
  if (!Load(ref_dir, "gat_burst_in.npy", &in) ||
      !Load(ref_dir, "gat_burst_alpha.npy", &alpha) ||
      !Load(ref_dir, "gat_burst_beta.npy", &beta) ||
      !Load(ref_dir, "gat_burst_out.npy", &want)) {
    std::fprintf(stderr, "FAIL: burst refs missing\n");
    failures = 4;
  } else {
    std::vector<float> ab(8);
    std::memcpy(ab.data(), alpha.data.data(), 4 * sizeof(float));
    std::memcpy(ab.data() + 4, beta.data.data(), 4 * sizeof(float));
    const uint32_t w = static_cast<uint32_t>(in.shape[1]);
    const uint32_t h = static_cast<uint32_t>(in.shape[0]);
    if (!RunOp(ctx, module, w, h, w * h, 0, in.data, ab, &got) ||
        !CheckGat("gat_burst1024_op0", got, want.data)) {
      ++failures;
    }
    // Case 2: decimate on the same crop (bit-exact).
    srp_proof::NpyArray want_dec;
    if (!Load(ref_dir, "decimate_burst_out.npy", &want_dec)) {
      std::fprintf(stderr, "FAIL: decimate burst ref missing\n");
      ++failures;
    } else {
      const std::vector<float> zeros(8, 0.0f);
      if (!RunOp(ctx, module, w, h, (w / 2) * (h / 2), 1, in.data, zeros,
                 &got) ||
          !CheckExact("decimate_burst1024_op1", got, want_dec.data)) {
        ++failures;
      }
    }
  }

  // Case 3/4: synthetic float fixtures vs the port's recorded GPU output
  // (same shader + device class => bit-exact). The CPU-envelope check for
  // these inputs already ran above on the burst; here we certify dispatch
  // fidelity: any deviation from the port's GPU bytes is our bug.
  srp_proof::NpyArray f_in, g_want, d_in, gd_want;
  if (!Load(fix_dir, "gat_in_raw.npy", &f_in) ||
      !Load(gpu_dir, "gpu_gat_out_vst.npy", &g_want) ||
      !Load(fix_dir, "decimate_in_raw.npy", &d_in) ||
      !Load(gpu_dir, "gpu_decimate_out_grey.npy", &gd_want)) {
    std::fprintf(stderr, "FAIL: parity fixtures or gpu refs missing\n");
    failures += 2;
  } else {
    std::vector<float> ab(8, 0.0f);
    for (int i = 0; i < 4; ++i) ab[i] = 1e-4f;  // gen_fixtures ALPHA
    for (int i = 4; i < 8; ++i) ab[i] = 1e-6f;  // gen_fixtures BETA
    const uint32_t w = static_cast<uint32_t>(f_in.shape[1]);
    const uint32_t h = static_cast<uint32_t>(f_in.shape[0]);
    if (!RunOp(ctx, module, w, h, w * h, 0, f_in.data, ab, &got) ||
        !CheckExact("gat_fixture32_op0_vs_gpu", got, g_want.data)) {
      ++failures;
    }
    const std::vector<float> zeros(8, 0.0f);
    if (!RunOp(ctx, module, w, h, (w / 2) * (h / 2), 1, d_in.data, zeros,
               &got) ||
        !CheckExact("decimate_fixture32_op1_vs_gpu", got, gd_want.data)) {
      ++failures;
    }
  }

  vkDestroyShaderModule(device, module, nullptr);
  srp::Destroy(ctx);
  if (failures == 0) std::printf("PASS: gat+decimate on-device within bounds\n");
  return failures == 0 ? 0 : 1;
}
